.documenticon { width: 36px; height: 36px; background: lineargradient(135deg, var(primary), var(secondary)); borderradius: var(radiussm); display: flex; alignitems: center; justifycontent: center; color: white; fontsize: 1.1rem; }
.documentinfo h4 { margin: 0 0 2px 0; fontsize: 0.85rem; color: var(text); }
