.optiongroup label { fontsize: 0.8rem; fontweight: 600; color: var(text); }
.actionbuttons { display: flex; gap: 12px; justifycontent: center; flexwrap: wrap; margintop: 30px; }
.primarybtn, .secondarybtn, .actionbtn, .buttonprimary { padding: 10px 16px; borderradius: var(radiusmd); border: 1px solid var(border); fontweight: 600; fontsize: 0.85rem; cursor: pointer; transition: all 0.2s var(transitioncurve); display: inlineflex; alignitems: center; gap: 8px; minheight: 42px; }
.primarybtn, .buttonprimary { background: lineargradient(135deg, var(primary), var(secondary)); color: white; bordercolor: var(primary); }
.primarybtn:hover, .buttonprimary:hover { transform: translateY(2px); boxshadow: 0 4px 15px rgba(var(primaryrgb), 0.4); }
.secondarybtn, .actionbtn { background: var(glassstrong); color: var(text); }
.secondarybtn:hover, .actionbtn:hover { background: var(glassstrong); bordercolor: var(primary); transform: translateY(1px); }
.resultsection { margintop: 30px; paddingtop: 20px; bordertop: 1px solid var(border); }
.resultsection h3 { fontsize: 1rem; fontweight: 600; marginbottom: 16px; color: var(text); }
.progresssection { margin: 20px 0; }
.statusindicator { padding: 15px; borderradius: var(radiusmd); margin: 10px 0; display: flex; alignitems: center; gap: 10px; fontweight: 600; }
.statusrunning { background: rgba(var(primaryrgb), 0.1); color: var(primary); border: 1px solid rgba(var(primaryrgb), 0.3); }
.statuscompleted { background: rgba(57, 255, 20, 0.1); color: var(secondary); border: 1px solid rgba(var(secondaryrgb), 0.3); }
.statuserror { background: rgba(239, 68, 68, 0.1); color: ef4444; border: 1px solid rgba(239, 68, 68, 0.3); }

/ Tab System Styles /
.tabselector, .molinputtabs, .archtabs, .robottabs { display: flex; gap: 5px; marginbottom: 20px; background: var(glass); borderradius: var(radiusmd); padding: 5px; }
.tabbtn { background: transparent; border: none; color: var(textmuted); padding: 8px 16px; borderradius: var(radiussm); cursor: pointer; transition: all 0.2s var(transitioncurve); fontweight: 500; fontsize: 0.85rem; }
.tabbtn.active, .tabbtn:hover { background: var(glassstrong); color: var(text); }
.tabcontent { display: none; }
.tabcontent.active { display: block; animation: fadeIn 0.4s ease; }

/ General Service Interface Components /
.glasscard { background: var(glass); border: 1px solid var(border); borderradius: var(radiusmd); padding: 15px; marginbottom: 15px; }
.uploadarea { border: 2px dashed var(border); borderradius: var(radiusmd); padding: 20px; textalign: center; cursor: pointer; transition: all 0.3s var(transitioncurve); background: rgba(0,0,0,0.1); }
.uploadarea:hover { bordercolor: var(primary); background: var(glassstrong); }
.uploadarea i { fontsize: 2rem; color: var(primary); marginbottom: 8px; display: block; }
.resultitem { display: flex; justifycontent: spacebetween; alignitems: center; padding: 8px 0; borderbottom: 1px solid var(border); }
.resultitem:lastchild { borderbottom: none; }
.followupsection { margintop: 20px; }

/ Specific Service Styles /
.sequenceinputwrapper { padding: 10px; }
.sequencestats { display: flex; justifycontent: spacebetween; alignitems: center; fontsize: 0.8rem; color: var(textmuted); margintop: 10px; }
.chainbuilder .chainitem { display: flex; gap: 10px; alignitems: flexstart; marginbottom: 10px; }
.chainbuilder .chainitem label { flexshrink: 0; paddingtop: 12px; }
.chainbuilder .chainitem textarea { flexgrow: 1; }
.chainbuilder .chainitem button { background: ef4444; color: white; border: none; borderradius: 50%; width: 24px; height: 24px; cursor: pointer; fontsize: 0.9rem; flexshrink: 0; margintop: 8px; }
.ligandinput .optiongroup, .ligandinputsection { marginbottom: 15px; }
.checkboxgrid { display: grid; gridtemplatecolumns: repeat(autofit, minmax(200px, 1fr)); gap: 10px; margin: 15px 0; }
.checkboxgrid label { display: flex; alignitems: center; gap: 8px; fontsize: 0.85rem; cursor: pointer; }
.robottypes { display: grid; gridtemplatecolumns: repeat(autofit, minmax(150px, 1fr)); gap: 15px; margin: 20px 0; }
.robotoption { background: var(glass); border: 2px solid var(border); borderradius: var(radiusmd); padding: 20px; textalign: center; cursor: pointer; transition: all 0.3s var(transitioncurve); }
.robotoption:hover, .robotoption.selected { bordercolor: var(primary); background: var(glassstrong); transform: translateY(3px); }
.robotoption i { fontsize: 2rem; color: var(primary); marginbottom: 10px; display: block; }

@media (maxwidth: 768px) {
    .sidebar { width: 100vw; }
    .maincontent { marginleft: 0; }
    .header { padding: 8px; }
    .welcometitle { fontsize: 1.8rem; }
    .statsgrid, .optionsgrid, .inputgrid, .checkboxgrid, .robottypes { gridtemplatecolumns: 1fr; }
    .serviceinterface { padding: 16px; }
    .interfacecontent { padding: 16px; }
    .actionbuttons { flexdirection: column; alignitems: stretch; }
}

